#!/usr/bin/env python3
"""Offline regression for a publishing run queued behind another publication."""
import os
from pathlib import Path
import re
import subprocess
import tempfile
import unittest


WORKFLOW = Path(__file__).resolve().parents[1] / 'workflows/harmonize.yml'


class PublicationCheckoutTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory(prefix='ammitto-publish-checkout-')
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name)
        self.env = dict(os.environ, GIT_CONFIG_GLOBAL=os.devnull,
                        GIT_CONFIG_NOSYSTEM='1', GIT_TERMINAL_PROMPT='0',
                        GIT_AUTHOR_NAME='Fixture', GIT_AUTHOR_EMAIL='fixture@example.test',
                        GIT_COMMITTER_NAME='Fixture', GIT_COMMITTER_EMAIL='fixture@example.test')
        self.origin = self.root / 'origin.git'
        self.writer = self.root / 'writer'
        self.git(self.root, 'init', '--bare', '--initial-branch=main', str(self.origin))
        self.git(self.root, 'clone', str(self.origin), str(self.writer))
        (self.writer / 'snapshot').write_text('initial\n')
        self.git(self.writer, 'add', 'snapshot')
        self.git(self.writer, 'commit', '-m', 'initial publication')
        self.git(self.writer, 'push', 'origin', 'main')
        self.event_sha = self.git(self.writer, 'rev-parse', 'HEAD').stdout.strip()
        # While the next run is queued, the preceding run advances main.
        (self.writer / 'previous-publication').write_text('must be retained\n')
        self.git(self.writer, 'add', 'previous-publication')
        self.git(self.writer, 'commit', '-m', 'preceding queued publication')
        self.git(self.writer, 'push', 'origin', 'main')
        self.previous_sha = self.git(self.writer, 'rev-parse', 'HEAD').stdout.strip()

    def git(self, cwd, *args, check=True):
        return subprocess.run(['git', *args], cwd=cwd, env=self.env, check=check,
                              text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    def checkout(self, ref):
        runner = self.root / 'runner'
        self.git(self.root, 'clone', '--no-checkout', str(self.origin), str(runner))
        self.git(runner, 'checkout', ref)
        return runner

    def publish(self, runner):
        (runner / 'snapshot').write_text('regenerated by queued run\n')
        self.git(runner, 'add', 'snapshot')
        self.git(runner, 'commit', '-m', 'queued publication')
        return self.git(runner, 'push', 'origin', 'HEAD:refs/heads/main', check=False)

    def configured_checkout(self):
        text = WORKFLOW.read_text()
        match = re.search(r'(?m)^      - uses: actions/checkout@v4\n'
                          r'        with:\n((?:          .*\n)+)', text)
        self.assertIsNotNone(match, 'publishing checkout must declare its configuration')
        refs = re.findall(r'(?m)^          ref: (.+)$', match[1])
        if not refs:
            return self.event_sha  # actions/checkout defaults to the queued event revision.
        self.assertEqual(refs, ['${{ github.event.repository.default_branch }}'])
        return 'main'

    def test_queued_run_starts_from_latest_default_branch_and_pushes(self):
        runner = self.checkout(self.configured_checkout())
        self.assertEqual(self.git(runner, 'rev-parse', 'HEAD').stdout.strip(),
                         self.previous_sha)
        result = self.publish(runner)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual((runner / 'previous-publication').read_text(),
                         'must be retained\n')
        self.assertEqual(self.git(self.origin, 'rev-parse', 'main^').stdout.strip(),
                         self.previous_sha)

    def test_old_event_revision_reproduces_non_fast_forward_rejection(self):
        result = self.publish(self.checkout(self.event_sha))
        self.assertNotEqual(result.returncode, 0)
        self.assertIn('rejected', result.stderr)
        self.assertEqual(self.git(self.origin, 'rev-parse', 'main').stdout.strip(),
                         self.previous_sha)

    def test_an_unrelated_writer_during_generation_is_not_overwritten(self):
        runner = self.checkout('main')
        (self.writer / 'concurrent-update').write_text('preserve this too\n')
        self.git(self.writer, 'add', 'concurrent-update')
        self.git(self.writer, 'commit', '-m', 'concurrent writer')
        self.git(self.writer, 'push', 'origin', 'main')
        concurrent_sha = self.git(self.writer, 'rev-parse', 'HEAD').stdout.strip()
        result = self.publish(runner)
        self.assertNotEqual(result.returncode, 0)
        self.assertEqual(self.git(self.origin, 'rev-parse', 'main').stdout.strip(),
                         concurrent_sha)

    def test_nondefault_dispatch_cannot_publish_to_default_branch(self):
        text = WORKFLOW.read_text()
        self.assertRegex(text, r"(?m)^  harmonize:\n"
                         r"    if: github.ref == format\('refs/heads/\{0\}', "
                         r"github.event.repository.default_branch\)$")


if __name__ == '__main__':
    unittest.main(verbosity=2)
